    class MySrv(zerorpc.Server):

        @zerorpc.rep
        def range(self, max):
            return list(range(max))

        @zerorpc.stream
        def xrange(self, max):
            return range(max)
    srv = MySrv(heartbeat=TIME_FACTOR * 4)
    srv.bind(endpoint)
    gevent.spawn(srv.run)
    client = zerorpc.Client(heartbeat=TIME_FACTOR * 4)
    client.connect(endpoint)
